// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 val, address logAddress) public {
        vm.assume(logAddress != address(0) && logAddress != address(c));
        c.Initialized();
        bool okSetMinSum;
        try c.SetMinSum(val) { okSetMinSum = true; } catch { okSetMinSum = false; }
        bool okSetLogFile;
        try c.SetLogFile(logAddress) { okSetLogFile = true; } catch { okSetLogFile = false; }
        assertTrue(!okSetMinSum && !okSetLogFile);
    }
}
